/*
 * gl_lock.c -- generated by LSTCS-P: serialises every GL call the game makes.
 *
 * The game uploads textures from a background thread (through a pbuffer EGL context)
 * while its render thread keeps drawing. vitaGL has no locking, so the two threads
 * corrupted its state during level loads and the render thread crashed in glClear.
 * Each GL entry point the game imports now takes one recursive lock first, so only
 * one thread is ever inside vitaGL at a time.
 */
#include "reimpl/gl_lock.h"
#include "reimpl/gl.h"
#include "utils/glutil.h"

#include <psp2/kernel/threadmgr.h>

static SceKernelLwMutexWork gl_mutex;
static volatile int gl_mutex_state = 0;   // 0 = not created, 1 = creating, 2 = ready

void gl_lock(void) {
    if (__atomic_load_n(&gl_mutex_state, __ATOMIC_ACQUIRE) != 2) {
        int expected = 0;
        if (__atomic_compare_exchange_n(&gl_mutex_state, &expected, 1, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
            sceKernelCreateLwMutex(&gl_mutex, "lstcs_gl", 0x02 /* recursive */, 0, NULL);
            __atomic_store_n(&gl_mutex_state, 2, __ATOMIC_RELEASE);
        } else {
            while (__atomic_load_n(&gl_mutex_state, __ATOMIC_ACQUIRE) != 2)
                sceKernelDelayThread(100);
        }
    }
    sceKernelLockLwMutex(&gl_mutex, 1, NULL);
}

void gl_unlock(void) {
    sceKernelUnlockLwMutex(&gl_mutex, 1);
}

void lk_glActiveTexture(GLenum texture) {
    gl_lock();
    ((void (*)(GLenum texture)) glActiveTexture_soloader)(texture);
    gl_unlock();
}

void lk_glAttachShader(GLuint prog, GLuint shad) {
    gl_lock();
    ((void (*)(GLuint prog, GLuint shad)) glAttachShader)(prog, shad);
    gl_unlock();
}

